import React, { useState, useEffect } from 'react';
import { Flashcard } from '../types';
import { Download, Copy, Check, RotateCcw, Pencil, Trash2, X, Lock, Sparkles, LayoutGrid, Layers, ArrowLeft, ArrowRight, BookOpen } from 'lucide-react';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import { useAuth } from '../contexts/AuthContext';
import PricingModal from './PricingModal';

interface FlashcardListProps {
  cards: Flashcard[];
  onReset: () => void;
  onUpdateCards: (cards: Flashcard[]) => void;
}

const FlashcardList: React.FC<FlashcardListProps> = ({ cards, onReset, onUpdateCards }) => {
  const { user } = useAuth();
  const [copied, setCopied] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<{ front: string; back: string }>({ front: '', back: '' });
  const [showPricing, setShowPricing] = useState(false);
  const [viewMode, setViewMode] = useState<'grid' | 'study'>('grid');
  const [studyIndex, setStudyIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  // Free Tier Limit
  const FREE_LIMIT = 5;
  const isFree = user?.plan === 'free';
  const visibleCards = isFree ? cards.slice(0, FREE_LIMIT) : cards;
  const hiddenCount = cards.length - visibleCards.length;

  // Reset study index when switching modes
  useEffect(() => {
    setStudyIndex(0);
    setIsFlipped(false);
  }, [viewMode]);

  const handleDownloadCSV = () => {
    if (isFree) {
        setShowPricing(true);
        return;
    }

    const csvContent = "data:text/csv;charset=utf-8," + 
      cards.map(c => {
        const front = `"${c.front.replace(/"/g, '""')}"`;
        const back = `"${c.back.replace(/"/g, '""')}"`;
        return `${front},${back}`;
      }).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "flashcards_anki.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleCopyQuizlet = () => {
    if (isFree) {
        setShowPricing(true);
        return;
    }
    const textContent = cards.map(c => `${c.front}\t${c.back}`).join("\n");
    navigator.clipboard.writeText(textContent);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const startEditing = (card: Flashcard) => {
    setEditingId(card.id);
    setEditForm({ front: card.front, back: card.back });
  };

  const saveEdit = (id: string) => {
    const updated = cards.map(c => c.id === id ? { ...c, ...editForm } : c);
    onUpdateCards(updated);
    setEditingId(null);
  };

  const deleteCard = (id: string) => {
    onUpdateCards(cards.filter(c => c.id !== id));
  };

  // Study Mode Navigation
  const nextCard = () => {
    setIsFlipped(false);
    setTimeout(() => {
        setStudyIndex((prev) => (prev + 1) % visibleCards.length);
    }, 150);
  };

  const prevCard = () => {
    setIsFlipped(false);
    setTimeout(() => {
        setStudyIndex((prev) => (prev - 1 + visibleCards.length) % visibleCards.length);
    }, 150);
  };

  return (
    <div className="w-full space-y-6 pb-12 animate-fade-in-up">
      <PricingModal isOpen={showPricing} onClose={() => setShowPricing(false)} />

      {/* --- Action Bar --- */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex flex-col lg:flex-row justify-between items-center gap-4 sticky top-[80px] z-30 backdrop-blur-md bg-white/90 supports-[backdrop-filter]:bg-white/60">

        {/* Left: Meta & Reset */}
        <div className="flex items-center gap-4 w-full lg:w-auto justify-between lg:justify-start">
            <div className="flex items-center gap-2">
                <button onClick={onReset} className="p-2 text-slate-400 hover:text-slate-700 hover:bg-slate-100 rounded-xl transition-colors" title="Create New Set">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h2 className="text-lg font-bold text-slate-800 leading-none">
                        Study Set
                    </h2>
                    <span className="text-xs font-medium text-slate-500">
                        {cards.length} cards generated
                    </span>
                </div>
            </div>

            {/* View Toggle (Mobile) */}
            <div className="flex lg:hidden bg-slate-100 p-1 rounded-lg">
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-1.5 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                >
                    <LayoutGrid size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('study')}
                    className={`p-1.5 rounded-md transition-all ${viewMode === 'study' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                >
                    <Layers size={18} />
                </button>
            </div>
        </div>

        {/* Center: View Toggle (Desktop) */}
        <div className="hidden lg:flex bg-slate-100/80 p-1.5 rounded-xl border border-slate-200/50">
            <button 
                onClick={() => setViewMode('grid')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
                <LayoutGrid size={16} />
                <span>Grid View</span>
            </button>
            <button 
                onClick={() => setViewMode('study')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${viewMode === 'study' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
                <BookOpen size={16} />
                <span>Study Mode</span>
            </button>
        </div>

        {/* Right: Actions */}
        <div className="flex items-center gap-2 w-full lg:w-auto">
          <button
            onClick={handleCopyQuizlet}
            className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-white border border-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm"
          >
             {isFree && <Lock size={14} className="text-slate-400" />}
            {copied ? <Check size={16} className="text-emerald-500" /> : <Copy size={16} />}
            {copied ? "Copied" : "Copy (Quizlet)"}
          </button>
          <button
            onClick={handleDownloadCSV}
            className={`
                flex-1 lg:flex-none flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold shadow-md transition-all
                ${isFree 
                    ? 'bg-slate-100 text-slate-400 cursor-pointer hover:bg-slate-200 border border-slate-200' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-lg shadow-indigo-500/20'}
            `}
          >
            {isFree ? <Lock size={16} /> : <Download size={16} />}
            <span>Export Anki</span>
          </button>
        </div>
      </div>

      {/* --- Main Content Area --- */}
      <div className="relative min-h-[500px]">
        {viewMode === 'grid' ? (
            /* Grid View */
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-24">
                <TransitionGroup component={null}>
                    {visibleCards.map((card) => (
                    <CSSTransition key={card.id} timeout={300} classNames="card">
                        <div className="group bg-white rounded-2xl shadow-sm border border-slate-200 hover:shadow-md hover:border-indigo-200 transition-all duration-300 overflow-hidden flex flex-col">
                        {editingId === card.id ? (
                            <div className="p-6 space-y-4 flex-1">
                                <div>
                                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Question / Term</label>
                                    <textarea 
                                        value={editForm.front}
                                        onChange={(e) => setEditForm({...editForm, front: e.target.value})}
                                        className="w-full p-3 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50"
                                        rows={2}
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Answer / Definition</label>
                                    <textarea 
                                        value={editForm.back}
                                        onChange={(e) => setEditForm({...editForm, back: e.target.value})}
                                        className="w-full p-3 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 bg-slate-50"
                                        rows={4}
                                    />
                                </div>
                                <div className="flex justify-end gap-2 pt-2">
                                    <button onClick={() => setEditingId(null)} className="px-3 py-2 text-slate-500 hover:bg-slate-100 rounded-lg text-sm font-medium">
                                        Cancel
                                    </button>
                                    <button onClick={() => saveEdit(card.id)} className="px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 shadow-sm">
                                        Save Changes
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <div className="flex flex-col h-full">
                                <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/30 flex justify-between items-center">
                                    <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2.5 py-1 rounded-full uppercase tracking-wide border border-indigo-100">
                                        {card.tag || 'General'}
                                    </span>
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => startEditing(card)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors">
                                            <Pencil size={16} />
                                        </button>
                                        <button onClick={() => deleteCard(card.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </div>
                                <div className="p-6 flex-1 flex flex-col gap-6">
                                    <div>
                                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Front</h3>
                                        <p className="text-slate-800 font-medium leading-relaxed text-lg">{card.front}</p>
                                    </div>
                                    <div className="border-t border-slate-100 pt-4 mt-auto">
                                        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Back</h3>
                                        <p className="text-slate-600 leading-relaxed">{card.back}</p>
                                    </div>
                                </div>
                            </div>
                        )}
                        </div>
                    </CSSTransition>
                    ))}
                </TransitionGroup>

                {/* Locked Overlay for Free Users */}
                {isFree && hiddenCount > 0 && (
                    <div className="col-span-1 md:col-span-2 relative mt-8">
                        <div className="absolute inset-0 bg-slate-50/50 backdrop-blur-[2px] z-0 rounded-2xl"></div>
                        <div className="relative z-10 flex flex-col items-center justify-center p-8 bg-white rounded-2xl border-2 border-dashed border-indigo-200 shadow-sm text-center">
                            <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mb-4">
                                <Lock size={32} />
                            </div>
                            <h3 className="text-xl font-bold text-slate-900 mb-2">
                                {hiddenCount} more cards hidden
                            </h3>
                            <p className="text-slate-500 mb-6 max-w-md mx-auto">
                                Upgrade to the Student plan to unlock all generated cards and enable unlimited exports.
                            </p>
                            <button 
                                onClick={() => setShowPricing(true)}
                                className="flex items-center justify-center gap-2 px-8 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl font-bold hover:shadow-lg hover:shadow-indigo-500/30 transition-all transform hover:-translate-y-0.5"
                            >
                                <Sparkles size={18} />
                                Unlock Full Set
                            </button>
                        </div>
                    </div>
                )}
            </div>
        ) : (
            /* Study Mode (Carousel) */
            <div className="flex flex-col items-center justify-center py-8">
                <div 
                    className="perspective-1000 w-full max-w-2xl h-[400px] cursor-pointer group relative"
                    onClick={() => setIsFlipped(!isFlipped)}
                >
                     <div className={`relative w-full h-full transition-all duration-500 preserve-3d shadow-2xl rounded-3xl ${isFlipped ? 'rotate-y-180' : ''}`}>
                        {/* Front */}
                        <div className="absolute inset-0 backface-hidden bg-white rounded-3xl border border-slate-200 flex flex-col items-center justify-center p-12 text-center">
                            <span className="absolute top-8 left-8 text-xs font-bold text-slate-400 uppercase tracking-widest">Question</span>
                            <span className="absolute top-8 right-8 text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-wide">
                                Card {studyIndex + 1} / {visibleCards.length}
                            </span>
                            <h3 className="text-3xl font-bold text-slate-800 leading-snug">{visibleCards[studyIndex]?.front}</h3>
                            <p className="absolute bottom-8 text-sm text-slate-400 font-medium flex items-center gap-2">
                                Click to Flip <RotateCcw size={14} />
                            </p>
                        </div>

                        {/* Back */}
                        <div className="absolute inset-0 backface-hidden rotate-y-180 bg-gradient-to-br from-slate-900 to-slate-800 rounded-3xl border border-slate-700 flex flex-col items-center justify-center p-12 text-center text-white">
                            <span className="absolute top-8 left-8 text-xs font-bold text-slate-500 uppercase tracking-widest">Answer</span>
                            <span className="absolute top-8 right-8 text-xs font-bold text-white/20 bg-white/10 px-3 py-1 rounded-full uppercase tracking-wide">
                                Card {studyIndex + 1} / {visibleCards.length}
                            </span>
                            <p className="text-xl md:text-2xl font-medium leading-relaxed">{visibleCards[studyIndex]?.back}</p>
                        </div>
                    </div>
                </div>

                {/* Navigation Controls */}
                <div className="flex items-center gap-6 mt-10">
                    <button 
                        onClick={prevCard}
                        className="p-4 bg-white border border-slate-200 rounded-full shadow-sm text-slate-600 hover:text-indigo-600 hover:border-indigo-200 transition-all hover:-translate-x-1"
                    >
                        <ArrowLeft size={24} />
                    </button>
                    <div className="text-sm font-semibold text-slate-500">
                        {studyIndex + 1} of {visibleCards.length}
                    </div>
                    <button 
                        onClick={nextCard}
                        className="p-4 bg-white border border-slate-200 rounded-full shadow-sm text-slate-600 hover:text-indigo-600 hover:border-indigo-200 transition-all hover:translate-x-1"
                    >
                        <ArrowRight size={24} />
                    </button>
                </div>

                <p className="mt-6 text-xs text-slate-400">
