import React, { useState } from 'react';
import NoteInput from './NoteInput';
import FlashcardList from './FlashcardList';
import { generateFlashcards } from '../services/geminiService';
import { Flashcard, AppState, GenerationConfig } from '../types';
import { AlertCircle, Moon, Loader2, Sparkles } from 'lucide-react';

const Dashboard: React.FC = () => {
  const [cards, setCards] = useState<Flashcard[]>([]);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleGenerate = async (notes: string, config: GenerationConfig) => {
    setAppState(AppState.GENERATING);
    setErrorMsg(null);
    try {
      const generatedCards = await generateFlashcards(notes, config);
      setCards(generatedCards);
      setAppState(AppState.REVIEW);
    } catch (err: any) {
      console.error(err);
      setErrorMsg(err.message || "Something went wrong.");
      setAppState(AppState.ERROR);
    }
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setCards([]);
    setErrorMsg(null);
  };

  const handleUpdateCards = (updatedCards: Flashcard[]) => {
    setCards(updatedCards);
  };

  return (
    <div className="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 animate-fade-in-up">

      {/* Top Bar Area (if needed for global dashboard actions) */}
      <div className="flex justify-between items-center mb-8">
          <div>
            {/* Breadcrumbs or greeting could go here */}
          </div>
          {/* Dark Mode Toggle (Mock) */}
          <button className="hidden md:flex p-2.5 rounded-xl bg-white shadow-sm border border-slate-200 text-slate-500 hover:text-indigo-600 hover:border-indigo-200 transition-all">
             <Moon size={20} />
          </button>
      </div>

      {/* Error Banner */}
      {appState === AppState.ERROR && (
        <div className="max-w-3xl mx-auto mb-8 p-4 bg-red-50 border border-red-200 rounded-2xl flex items-center gap-4 text-red-800 shadow-sm animate-fade-in-up">
          <div className="p-2 bg-red-100 rounded-full">
            <AlertCircle size={24} />
          </div>
          <div className="flex-1">
            <h3 className="font-bold">Generation Failed</h3>
            <p className="text-sm text-red-700 mt-1">{errorMsg}</p>
          </div>
          <button 
            onClick={() => setAppState(AppState.IDLE)} 
            className="px-5 py-2.5 bg-white border border-red-200 rounded-xl text-sm font-bold text-red-600 hover:bg-red-50 transition-colors"
          >
            Try Again
          </button>
        </div>
      )}

      {/* --- State: Generating --- */}
      {appState === AppState.GENERATING && (
        <div className="min-h-[60vh] flex flex-col items-center justify-center text-center animate-fade-in-up">
            <div className="relative mb-8">
                <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 animate-pulse rounded-full"></div>
                <div className="relative bg-white p-6 rounded-3xl shadow-xl border border-indigo-50">
                    <Loader2 size={48} className="text-indigo-600 animate-spin" />
                </div>
            </div>
            <h2 className="text-2xl font-bold text-slate-900 mb-2">Analyzing your notes...</h2>
            <p className="text-slate-500 max-w-md mx-auto">
                Our AI is extracting key concepts and definitions to create the perfect flashcards for you.
            </p>

            <div className="mt-10 flex flex-col gap-3 w-64 max-w-full opacity-80">
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                    <div className="h-full bg-indigo-600 animate-[shimmer_2s_infinite] w-full origin-left"></div>
                </div>
                <p className="text-xs text-center text-slate-400 font-medium">Processing large text blocks...</p>
            </div>
        </div>
      )}

      {/* --- State: Input (IDLE) --- */}
      {(appState === AppState.IDLE || appState === AppState.ERROR) && (
        <div className="flex flex-col items-center w-full">
            <header className="text-center mb-10 space-y-3">
                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-50 border border-indigo-100 text-indigo-700 text-xs font-bold uppercase tracking-wider mb-2">
                    <Sparkles size={12} />
                    <span>New Study Set</span>
                </div>
                <h2 className="text-4xl md:text-5xl font-black text-slate-900 tracking-tight">
                    What are you studying today?
                </h2>
                <p className="text-lg text-slate-500 max-w-2xl mx-auto leading-relaxed">
                    Paste your lecture notes, article, or textbook summary below. We'll handle the rest.
                </p>
            </header>

            <div className="w-full max-w-5xl">
                <NoteInput onGenerate={handleGenerate} isGenerating={false} />
            </div>
        </div>
      )}

      {/* --- State: Review --- */}
      {appState === AppState.REVIEW && (
        <FlashcardList 
          cards={cards} 
          onReset={handleReset} 
          onUpdateCards={handleUpdateCards} 
        />
      )}

    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState, useRef } from 'react';
import { Sparkles, Brain, Download, FileText, ArrowRight, Zap, GraduationCap, Microscope, Gavel, Book, Code } from 'lucide-react';

interface HeroProps {
  onStart: () => void;
}

const Hero: React.FC<HeroProps> = ({ onStart }) => {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const [typedText, setTypedText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [loopNum, setLoopNum] = useState(0);
  const [typingSpeed, setTypingSpeed] = useState(150);
