                        </h3>
                        <button onClick={() => setIsAddBudgetModalOpen(true)} className="p-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg border border-white/10 transition-colors shadow-sm active:scale-95">
                            <Plus className="w-4 h-4" />
                        </button>
                    </div>

                    {budgets.length === 0 ? (
