const BudgetCard: React.FC<{ budget: Budget, transactions: Transaction[], onDelete?: (id: string) => void, formatCurrency: (amount: number) => string | React.ReactNode }> = ({ budget, transactions, onDelete, formatCurrency }) => {
    const { spent, daysLeft } = useMemo(() => {
        const now = new Date();
        let currentCycleStart: Date;
        let currentCycleEnd: Date;
        let dLeft = 0;

        if (budget.startDate) {
            const startDate = new Date(budget.startDate);
            const timeDiff = now.getTime() - startDate.getTime();
            const daysPassed = Math.floor(timeDiff / (1000 * 3600 * 24));
            const cyclesPassed = Math.floor(daysPassed / 30);

            currentCycleStart = new Date(startDate);
            currentCycleStart.setDate(currentCycleStart.getDate() + (cyclesPassed * 30));

            currentCycleEnd = new Date(currentCycleStart);
            currentCycleEnd.setDate(currentCycleEnd.getDate() + 30);
            dLeft = 30 - (daysPassed % 30);
        } else {
            currentCycleStart = new Date(now.getFullYear(), now.getMonth(), 1);
            currentCycleEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);
            const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
            dLeft = endOfMonth.getDate() - now.getDate();
        }

        const totalSpent = transactions
            .filter(t => 
                t.category === budget.category && 
                t.type === TransactionType.EXPENSE && 
                new Date(t.date) >= currentCycleStart &&
                new Date(t.date) < currentCycleEnd
            )
            .reduce((acc, t) => acc + t.amount, 0);

        return { spent: totalSpent, daysLeft: Math.max(0, dLeft) };
    }, [budget.category, transactions, budget.startDate]);

    const percentage = Math.min((spent / budget.limit) * 100, 100);
    const remaining = budget.limit - spent;
    const isOver = spent > budget.limit;
    const isWarning = percentage > 80 && !isOver;
    let statusColor = "bg-emerald-500";
    if (isWarning) statusColor = "bg-amber-500";
    else if (isOver) statusColor = "bg-rose-500";

    return (
        <div className="glass-card p-4 rounded-2xl relative group overflow-hidden border border-white/5 hover:border-white/10 transition-all bg-slate-900/60 hover:bg-slate-900/80">
            {onDelete && (<button onClick={() => onDelete(budget.id)} className="absolute top-3 right-3 p-1.5 bg-slate-900 rounded-lg text-slate-600 hover:text-rose-400 hover:bg-rose-950/30 opacity-0 group-hover:opacity-100 transition-all z-20"><Trash2 className="w-3 h-3" /></button>)}

            <div className="flex items-center gap-3 mb-3">
                <div className={`p-2 rounded-lg bg-slate-800 border border-white/5 ${isOver ? 'ring-1 ring-rose-500/30' : ''}`}>
                    <PieChart className={`w-4 h-4 ${isOver ? 'text-rose-400' : 'text-indigo-400'}`} />
                </div>
                <div className="min-w-0">
                    <h4 className="font-bold text-white text-xs truncate">{budget.category}</h4>
                    <p className={`text-[10px] font-bold uppercase tracking-wide ${isOver ? 'text-rose-400' : 'text-slate-500'}`}>
                        {isOver ? 'Over Limit' : `${percentage.toFixed(0)}% Used`}
                    </p>
                </div>
            </div>

            <div className="w-full bg-slate-950 h-1.5 rounded-full overflow-hidden flex border border-white/5 mb-2"><div className={`h-full rounded-full transition-all duration-1000 ${statusColor}`} style={{ width: `${percentage}%` }}></div></div>

            <div className="flex justify-between items-end">
                <div className="text-[10px] font-medium text-slate-500 flex items-center gap-1">
                    <Clock className="w-3 h-3" /> {daysLeft}d left
                </div>
                <div className="text-right">
                    <span className={`text-xs font-bold block ${remaining < 0 ? 'text-rose-400' : 'text-white'}`}>{remaining < 0 ? '-' : ''}{formatCurrency(Math.abs(remaining))}</span>
                    <span className="text-[9px] text-slate-600 font-bold uppercase">Remaining</span>
                </div>
            </div>
        </div>
    );
};

