                    </h2>
                    <p className="text-slate-400 mt-2 font-medium">Control your monthly burn rate and build wealth.</p>
                </div>

                {/* Streak Banner - Compact & Modern */}
                <div className="bg-gradient-to-r from-amber-500/10 to-orange-500/10 border border-amber-500/20 rounded-2xl p-1 pr-4 flex items-center gap-3 shadow-lg shadow-amber-900/10 backdrop-blur-sm">
                    <div className="bg-gradient-to-br from-amber-400 to-orange-600 w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-md">
                        <Zap className="w-5 h-5 fill-white animate-pulse" />
                    </div>
                    <div>
                        <div className="text-[10px] font-bold text-amber-500 uppercase tracking-widest leading-none mb-0.5">Discipline Streak</div>
                        <div className="text-lg font-black text-white leading-none">{streak} <span className="text-xs text-slate-400 font-bold">DAYS</span></div>
                    </div>
                </div>
            </div>

            {/* Split View Container */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">

                {/* --- Left Column: Monthly Limits (Budgets) --- */}
                <div className="flex flex-col gap-6">
                    {/* Budget Overview Header */}
                    <div className="bg-[#0f172a] border border-white/10 rounded-[2rem] p-6 shadow-xl relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 rounded-full blur-[80px] -mr-16 -mt-16"></div>

                        <div className="flex justify-between items-center mb-6 relative z-10">
                            <div>
                                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                                    <Shield className="w-5 h-5 text-indigo-400" />
                                    Monthly Limits
                                </h3>
                                <p className="text-xs text-slate-500 font-medium mt-1">Total Category Caps</p>
                            </div>
                            <button 
                                onClick={() => setIsAddBudgetModalOpen(true)} 
                                className="w-8 h-8 flex items-center justify-center rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/20 transition-all active:scale-95"
                            >
                                <Plus className="w-5 h-5" />
                            </button>
                        </div>

                        {budgets.length > 0 ? (
                            <div className="relative z-10">
                                <div className="flex justify-between items-end mb-2">
                                    <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Aggregate Utilization</span>
                                    <span className={`text-xs font-black ${budgetStats.percentage > 100 ? 'text-rose-400' : 'text-emerald-400'}`}>
                                        {budgetStats.percentage.toFixed(0)}%
                                    </span>
                                </div>
                                <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5 mb-3">
                                    <div 
                                        className={`h-full rounded-full transition-all duration-1000 ${budgetStats.percentage > 100 ? 'bg-rose-500' : budgetStats.percentage > 80 ? 'bg-amber-500' : 'bg-indigo-500'}`} 
                                        style={{ width: `${Math.min(budgetStats.percentage, 100)}%` }}
                                    ></div>
                                </div>
                                <div className="flex justify-between text-xs font-medium text-slate-500">
                                    <span>{formatCurrency(budgetStats.totalSpent)} Spent</span>
                                    <span>{formatCurrency(budgetStats.totalLimit)} Limit</span>
                                </div>
                            </div>
                        ) : (
                            <div className="text-center py-6">
                                <p className="text-xs text-slate-500 font-medium">No limits configured.</p>
                            </div>
                        )}
                    </div>

                    {/* Budget Cards Grid */}
                    {budgets.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-center border-2 border-dashed border-slate-800 rounded-[2rem] bg-slate-900/20">
                            <div className="w-14 h-14 rounded-full bg-slate-800 flex items-center justify-center mb-4 text-slate-600 shadow-inner"><PieChart className="w-7 h-7" /></div>
                            <p className="text-slate-400 text-sm font-bold mb-4">Take control of your spend.</p>
                            <button onClick={() => setIsAddBudgetModalOpen(true)} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black uppercase tracking-widest rounded-xl transition-all shadow-lg">Set First Limit</button>
