export default Goals;

import React, { useEffect, useState, useMemo } from 'react';
import { Target, Trophy, Plane, Home, TrendingUp, Plus, DollarSign, Laptop, Check, Star, XCircle, Wallet, Gift, AlertCircle, PieChart, Trash2, Calendar, Clock, AlertTriangle, Zap, Shield, Edit2 } from 'lucide-react';
import { Goal, Budget, Transaction, TransactionType, Category } from '../types';
import confetti from 'canvas-confetti';

interface GoalsProps {
  goals?: Goal[];
  budgets?: Budget[];
  transactions?: Transaction[];
  onAddGoal?: (goal: Goal) => void;
  onUpdateGoal?: (goal: Goal) => void;
  onAddBudget?: (budget: Budget) => void;
  onDeleteBudget?: (id: string) => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
}

const Goals: React.FC<GoalsProps> = ({ goals = [], budgets = [], transactions = [], onAddGoal, onUpdateGoal, onAddBudget, onDeleteBudget, formatCurrency }) => {
    const [isAddGoalModalOpen, setIsAddGoalModalOpen] = useState(false);
    const [isAddBudgetModalOpen, setIsAddBudgetModalOpen] = useState(false);
    const [selectedGoal, setSelectedGoal] = useState<Goal | null>(null);
    const [depositAmount, setDepositAmount] = useState('');
    const [streak, setStreak] = useState(0);

    // --- STREAK ALGORITHM (PRESERVED) ---
    useEffect(() => {
        const lastVisit = localStorage.getItem('nova_last_visit');
        const currentStreak = parseInt(localStorage.getItem('nova_streak') || '0');
        const today = new Date().toDateString();

        if (lastVisit !== today) {
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            if (lastVisit === yesterday.toDateString()) {
                const newStreak = currentStreak + 1;
                setStreak(newStreak);
                localStorage.setItem('nova_streak', newStreak.toString());
            } else {
                setStreak(1);
                localStorage.setItem('nova_streak', '1');
            }
            localStorage.setItem('nova_last_visit', today);
        } else {
            setStreak(currentStreak || 1);
        }
    }, []);

    const handleDeposit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedGoal || !depositAmount) return;

        const amount = parseFloat(depositAmount);
        const newAmount = selectedGoal.currentAmount + amount;

        const updatedGoal = { ...selectedGoal, currentAmount: newAmount };
        if (onUpdateGoal) onUpdateGoal(updatedGoal);

        if (newAmount >= selectedGoal.targetAmount && selectedGoal.currentAmount < selectedGoal.targetAmount) {
             confetti({
                particleCount: 150,
                spread: 100,
                origin: { y: 0.6 },
                colors: ['#6366f1', '#ec4899', '#10b981', '#fbbf24']
            });
        }
        setSelectedGoal(null);
        setDepositAmount('');
    };

    // Aggregate Budget Stats for the Summary Header
    const budgetStats = useMemo(() => {
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();
        let totalLimit = 0;
        let totalSpent = 0;

        budgets.forEach(b => {
            totalLimit += b.limit;
            const spent = transactions
                .filter(t => 
                    t.category === b.category && 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getMonth() === currentMonth &&
                    new Date(t.date).getFullYear() === currentYear
                )
                .reduce((acc, t) => acc + t.amount, 0);
            totalSpent += spent;
        });

        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
        const daysLeft = daysInMonth - now.getDate();

        return { 
            totalLimit, 
            totalSpent, 
            percentage: totalLimit > 0 ? (totalSpent / totalLimit) * 100 : 0,
            daysLeft: Math.max(0, daysLeft)
        };
    }, [budgets, transactions]);

    return (
        <div className="space-y-8 animate-fade-in pb-10">
            {/* Header Section */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                        <Target className="w-8 h-8 text-indigo-500" />
                        Goals & Limits
                    </h2>
                    <p className="text-slate-400 mt-2 font-medium">Control your monthly burn rate and build wealth systematically.</p>
                </div>

                {/* Streak Badge - Compact & Modern */}
                <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-2 pr-5 flex items-center gap-3 shadow-lg backdrop-blur-sm">
                    <div className="bg-gradient-to-br from-amber-400 to-orange-600 w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-md">
                        <Zap className="w-5 h-5 fill-white animate-pulse" />
                    </div>
                    <div>
                        <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest leading-none mb-1">Current Streak</div>
                        <div className="text-xl font-black text-white leading-none">{streak} <span className="text-xs text-amber-500 font-bold">DAYS</span></div>
                    </div>
                </div>
            </div>

            {/* Split View Container */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">

                {/* --- Left Column: Monthly Limits (Monarch Style) --- */}
                <div className="flex flex-col gap-6">

                    {/* Aggregate Summary Card */}
                    <div className="relative p-8 rounded-[2.5rem] bg-[#0f172a] border border-white/10 shadow-2xl overflow-hidden group">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-[80px] -mr-16 -mt-16 group-hover:bg-indigo-500/15 transition-colors"></div>

                        <div className="relative z-10">
                            <div className="flex justify-between items-start mb-6">
                                <div>
                                    <div className="flex items-center gap-2 mb-1">
                                        <div className="p-1.5 bg-indigo-500/20 rounded-lg text-indigo-400"><Shield className="w-4 h-4" /></div>
                                        <h3 className="text-sm font-bold text-slate-300">Monthly Limits</h3>
                                    </div>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest pl-1">Total Category Caps</p>
                                </div>
                                <button 
                                    onClick={() => setIsAddBudgetModalOpen(true)} 
                                    className="p-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl border border-white/5 transition-all active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="flex items-baseline gap-2 mb-4">
                                <span className={`text-5xl font-black tracking-tighter ${budgetStats.totalSpent > budgetStats.totalLimit ? 'text-rose-500' : 'text-white'}`}>
                                    {formatCurrency(budgetStats.totalSpent)}
                                </span>
                                <span className="text-xl font-bold text-slate-500">
                                    / {formatCurrency(budgetStats.totalLimit)}
                                </span>
                            </div>

                            <div className="h-4 w-full bg-slate-800/50 rounded-full overflow-hidden mb-3 border border-white/5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${budgetStats.percentage > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-blue-500 to-indigo-500'}`} 
                                    style={{ width: `${Math.min(budgetStats.percentage, 100)}%` }}
                                ></div>
                            </div>

                            <div className="flex justify-between text-xs font-bold text-slate-400">
                                <span>{budgetStats.percentage.toFixed(0)}% Used</span>
                                <span>{budgetStats.daysLeft} Days Left</span>
                            </div>
                        </div>
                    </div>

                    {/* Budget Smart Cards Grid */}
                    {budgets.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-center border-2 border-dashed border-slate-800 rounded-[2rem] bg-slate-900/20">
                            <div className="w-14 h-14 rounded-full bg-slate-800 flex items-center justify-center mb-4 text-slate-600 shadow-inner"><PieChart className="w-7 h-7" /></div>
                            <p className="text-slate-400 text-sm font-bold mb-4">Take control of your spend.</p>
                            <button onClick={() => setIsAddBudgetModalOpen(true)} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black uppercase tracking-widest rounded-xl transition-all shadow-lg">Set First Limit</button>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 gap-4">
                            {budgets.map((budget) => (
                                <BudgetSmartCard key={budget.id} budget={budget} transactions={transactions} onDelete={onDeleteBudget} formatCurrency={formatCurrency} />
                            ))}
                        </div>
                    )}
                </div>

                {/* --- Right Column: Savings Targets (Goals) --- */}
                <div className="flex flex-col gap-6">
                    <div className="flex justify-between items-center px-2">
                        <div>
                            <h3 className="text-xl font-bold text-white flex items-center gap-2">
                                <Target className="w-5 h-5 text-emerald-400" />
                                Savings Targets
                            </h3>
                        </div>
                        <button 
                            onClick={() => setIsAddGoalModalOpen(true)} 
                            className="flex items-center gap-2 px-4 py-2 bg-emerald-600/10 hover:bg-emerald-600/20 text-emerald-400 rounded-xl border border-emerald-500/20 text-xs font-bold uppercase tracking-wider transition-all"
                        >
                            <Plus className="w-4 h-4" /> New Goal
                        </button>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {goals.map((goal) => {
                            const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                            const isCompleted = progress >= 100;
                            return (
                                <div 
                                    key={goal.id} 
                                    onClick={() => setSelectedGoal(goal)} 
                                    className={`group relative p-6 rounded-[2.5rem] border transition-all duration-300 cursor-pointer overflow-hidden bg-[#0f172a] hover:bg-slate-900 flex flex-col justify-between min-h-[200px] ${isCompleted ? 'border-emerald-500/30 shadow-[0_0_30px_rgba(16,185,129,0.1)]' : 'border-white/5 hover:border-white/10 hover:shadow-xl'}`}
                                >
                                    <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${goal.color} opacity-5 blur-[50px] rounded-full -mr-10 -mt-10 group-hover:opacity-15 transition-opacity`}></div>

                                    <div className="flex justify-between items-start mb-6 relative z-10">
                                        <div className={`p-3 rounded-2xl bg-gradient-to-br ${goal.color} shadow-lg text-white ring-1 ring-white/10 group-hover:scale-110 transition-transform duration-300`}>
                                            {goal.icon === 'plane' && <Plane className="w-5 h-5" />}
                                            {goal.icon === 'shield' && <Target className="w-5 h-5" />}
                                            {goal.icon === 'laptop' && <Laptop className="w-5 h-5" />}
                                            {goal.icon === 'home' && <Home className="w-5 h-5" />}
                                            {!['plane','shield','laptop','home'].includes(goal.icon) && <Star className="w-5 h-5" />}
                                        </div>
                                        {isCompleted ? (
                                            <div className="w-8 h-8 rounded-full bg-emerald-500 flex items-center justify-center shadow-lg shadow-emerald-500/40 animate-bounce">
                                                <Check className="w-4 h-4 text-white" />
                                            </div>
                                        ) : (
                                            <span className="text-xs font-black text-slate-500 bg-slate-950/50 px-3 py-1 rounded-lg border border-white/5">
                                                {new Date(goal.deadline).getFullYear()}
                                            </span>
                                        )}
                                    </div>

                                    <div className="relative z-10 space-y-3 mt-auto">
                                        <h3 className="font-bold text-white text-lg truncate mb-1">{goal.name}</h3>
                                        <div className="flex items-baseline gap-1 text-slate-300">
                                            <span className="text-2xl font-black text-white tracking-tight">{formatCurrency(goal.currentAmount)}</span>
                                        </div>

                                        <div className="w-full bg-slate-950 h-2 rounded-full overflow-hidden border border-white/5">
                                            <div className={`h-full rounded-full transition-all duration-1000 ${isCompleted ? 'bg-emerald-500' : `bg-gradient-to-r ${goal.color}`}`} style={{ width: `${progress}%` }}></div>
                                        </div>

                                        <div className="flex justify-between items-center text-[10px] font-bold text-slate-500 pt-1">
                                            <span>{progress.toFixed(0)}% Complete</span>
                                            <span>Target: {formatCurrency(goal.targetAmount)}</span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}

                        <button 
                            onClick={() => setIsAddGoalModalOpen(true)} 
                            className="border-2 border-dashed border-slate-800 rounded-[2.5rem] flex flex-col items-center justify-center p-6 text-slate-600 hover:border-emerald-500/30 hover:text-emerald-400 hover:bg-emerald-500/5 transition-all group min-h-[200px]"
                        >
                            <div className="w-14 h-14 rounded-full bg-slate-800 group-hover:bg-emerald-500/20 flex items-center justify-center mb-4 transition-colors ring-1 ring-white/5 group-hover:ring-emerald-500/30">
                                <Plus className="w-6 h-6 group-hover:rotate-90 transition-transform duration-300" />
                            </div>
                            <span className="font-bold text-xs uppercase tracking-widest">Create Target</span>
                        </button>
                    </div>
                </div>
            </div>

            {isAddGoalModalOpen && onAddGoal && (<AddGoalModal onClose={() => setIsAddGoalModalOpen(false)} onSubmit={onAddGoal} />)}
            {isAddBudgetModalOpen && onAddBudget && (<AddBudgetModal onClose={() => setIsAddBudgetModalOpen(false)} onSubmit={onAddBudget} />)}
            {selectedGoal && onUpdateGoal && (<DepositModal goal={selectedGoal} amount={depositAmount} setAmount={setDepositAmount} onClose={() => setSelectedGoal(null)} onSubmit={handleDeposit} />)}
        </div>
    );
};

const BudgetSmartCard: React.FC<{ budget: Budget, transactions: Transaction[], onDelete?: (id: string) => void, formatCurrency: (amount: number) => string | React.ReactNode }> = ({ budget, transactions, onDelete, formatCurrency }) => {
    const { spent, daysLeft } = useMemo(() => {
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();
        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
        const dLeft = daysInMonth - now.getDate();

        const totalSpent = transactions
            .filter(t => 
                t.category === budget.category && 
                t.type === TransactionType.EXPENSE && 
                new Date(t.date).getMonth() === currentMonth &&
                new Date(t.date).getFullYear() === currentYear
            )
            .reduce((acc, t) => acc + t.amount, 0);

        return { spent: totalSpent, daysLeft: Math.max(1, dLeft) }; 
    }, [budget.category, transactions]);

    const remaining = budget.limit - spent;
    const percentage = Math.min((spent / budget.limit) * 100, 100);
    const isOver = spent > budget.limit;
    const safeDaily = Math.max(0, remaining / daysLeft);

    // Theme Logic based on Utilization
    let statusColor = 'bg-emerald-500';
    let textColor = 'text-emerald-400';
    let bgTint = 'bg-emerald-500/10';
    let borderColor = 'border-white/5';
    let icon = <PieChart className="w-5 h-5" />;

    if (isOver) {
        statusColor = 'bg-rose-500';
        textColor = 'text-rose-400';
        bgTint = 'bg-rose-500/10';
        borderColor = 'border-rose-500/20';
        icon = <AlertTriangle className="w-5 h-5" />;
    } else if (percentage > 80) {
        statusColor = 'bg-amber-500';
        textColor = 'text-amber-400';
        bgTint = 'bg-amber-500/10';
        borderColor = 'border-amber-500/20';
    }

    return (
        <div className={`bg-[#0f172a] rounded-[1.5rem] p-5 border hover:border-white/10 transition-all shadow-lg flex flex-col gap-4 relative group ${borderColor}`}>
            {onDelete && (
                <button 
                    onClick={() => onDelete(budget.id)} 
                    className="absolute top-4 right-4 text-slate-600 hover:text-rose-400 opacity-0 group-hover:opacity-100 transition-all p-1 hover:bg-white/5 rounded"
                >
                    <Trash2 className="w-3.5 h-3.5" />
                </button>
            )}

            <div className="flex items-center gap-4">
                <div className={`p-3 rounded-xl ${bgTint} ${textColor}`}>
                    {icon}
                </div>
                <div className="flex-1">
                    <h4 className="font-bold text-white text-sm">{budget.category}</h4>
                    <p className={`text-[10px] font-bold uppercase tracking-wider ${textColor}`}>
                        {formatCurrency(spent)} <span className="text-slate-500">spent</span>
                    </p>
                </div>
                <div className="text-right">
                    <div className="font-bold text-white">{formatCurrency(budget.limit)}</div>
                    <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest text-right">Limit</div>
                </div>
            </div>

            <div className="w-full bg-slate-950 h-1.5 rounded-full overflow-hidden flex border border-white/5">
                <div className={`h-full rounded-full transition-all duration-1000 ${statusColor}`} style={{ width: `${percentage}%` }}></div>
            </div>

            <div className="flex justify-between items-center pt-2 border-t border-white/5">
                <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-500">
                    <Clock className="w-3 h-3" /> {daysLeft} Days Left
                </div>
                {!isOver && (
                    <div className="text-[10px] font-medium text-slate-400">
                        Safe Daily: <span className="text-white font-bold">{formatCurrency(safeDaily)}</span>
                    </div>
                )}
            </div>
        </div>
    );
};

const AddGoalModal: React.FC<{ onClose: () => void, onSubmit: (g: Goal) => void }> = ({ onClose, onSubmit }) => {
    const [name, setName] = useState('');
    const [target, setTarget] = useState('');
    const [date, setDate] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const inputDate = new Date(date);

        if (isNaN(inputDate.getTime())) {
            setError("Please enter a valid date.");
            return;
        }

        if (inputDate < today) {
            setError("Goal deadline cannot be in the past.");
            return;
        }

        const maxDate = new Date();
        maxDate.setFullYear(maxDate.getFullYear() + 50);
        if (inputDate > maxDate) {
            setError("Date exceeds valid range (50 years). Please enter a closer target.");
            return;
        }

        const newGoal: Goal = { 
            id: Date.now().toString(), 
            name, 
            targetAmount: parseFloat(target), 
            currentAmount: 0, 
            deadline: date, 
            icon: 'star', 
            color: 'from-pink-500 to-rose-500' 
        };
        onSubmit(newGoal);
        onClose();
    };

    const minDate = new Date().toISOString().split('T')[0];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="bg-[#0f172a] border border-white/10 rounded-[2rem] w-full max-w-sm shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5">
