                        <Target className="w-8 h-8 text-indigo-500" />
                        Goals & Limits
                    </h2>
                    <p className="text-slate-400 mt-2 font-medium">Control your monthly burn rate and build wealth systematically.</p>
                </div>

                {/* Streak Badge - Compact & Modern */}
                <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-2 pr-5 flex items-center gap-3 shadow-lg backdrop-blur-sm">
