                            <div className="h-4 w-full bg-slate-800/50 rounded-full overflow-hidden mb-3 border border-white/5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${budgetStats.percentage > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-blue-500 to-indigo-500'}`} 
