                                <span>{budgetStats.daysLeft} Days Left</span>
                            </div>
                        </div>
                    </div>

                    {/* Budget Smart Cards Grid */}
                    {budgets.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-center border-2 border-dashed border-slate-800 rounded-[2rem] bg-slate-900/20">
                            <div className="w-14 h-14 rounded-full bg-slate-800 flex items-center justify-center mb-4 text-slate-600 shadow-inner"><PieChart className="w-7 h-7" /></div>
                            <p className="text-slate-400 text-sm font-bold mb-4">Take control of your spend.</p>
                            <button onClick={() => setIsAddBudgetModalOpen(true)} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-black uppercase tracking-widest rounded-xl transition-all shadow-lg">Set First Limit</button>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 gap-4">
                            {budgets.map((budget) => (
                                <BudgetSmartCard key={budget.id} budget={budget} transactions={transactions} onDelete={onDeleteBudget} formatCurrency={formatCurrency} />
                            ))}
                        </div>
                    )}
                </div>

                {/* --- Right Column: Savings Targets (Goals) --- */}
                <div className="flex flex-col gap-6">
                    <div className="flex justify-between items-center px-2">
                        <div>
                            <h3 className="text-xl font-bold text-white flex items-center gap-2">
                                <Target className="w-5 h-5 text-emerald-400" />
                                Savings Targets
                            </h3>
                        </div>
                        <button 
                            onClick={() => setIsAddGoalModalOpen(true)} 
                            className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 backdrop-blur-md text-white rounded-xl border border-white/10 text-xs font-bold uppercase tracking-wider transition-all shadow-lg"
                        >
                            <Plus className="w-4 h-4" /> New Goal
