                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {goals.map((goal) => {
                            const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                            const isCompleted = progress >= 100;
                            return (
                                <div 
                                    key={goal.id} 
                                    onClick={() => setSelectedGoal(goal)} 
                                    className={`group relative p-6 rounded-[2.5rem] border transition-all duration-300 cursor-pointer overflow-hidden bg-[#0f172a] hover:bg-slate-900 flex flex-col justify-between min-h-[200px] ${isCompleted ? 'border-emerald-500/30 shadow-[0_0_30px_rgba(16,185,129,0.1)]' : 'border-white/5 hover:border-white/10 hover:shadow-xl'}`}
                                >
