};

const AddGoalModal: React.FC<{ onClose: () => void, onSubmit: (g: Goal) => void }> = ({ onClose, onSubmit }) => {
    const [name, setName] = useState('');
    const [target, setTarget] = useState('');
    const [date, setDate] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const inputDate = new Date(date);

        if (isNaN(inputDate.getTime())) {
            setError("Please enter a valid date.");
            return;
        }

        if (inputDate < today) {
            setError("Goal deadline cannot be in the past.");
            return;
        }

        const maxDate = new Date();
        maxDate.setFullYear(maxDate.getFullYear() + 50);
        if (inputDate > maxDate) {
            setError("Date exceeds valid range (50 years). Please enter a closer target.");
            return;
        }

        const newGoal: Goal = { 
            id: Date.now().toString(), 
            name, 
            targetAmount: parseFloat(target), 
            currentAmount: 0, 
            deadline: date, 
            icon: 'star', 
            color: 'from-pink-500 to-rose-500' 
        };
        onSubmit(newGoal);
        onClose();
    };

    const minDate = new Date().toISOString().split('T')[0];

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="bg-[#0f172a] border border-white/10 rounded-[2rem] w-full max-w-sm shadow-2xl overflow-hidden animate-slide-up relative ring-1 ring-white/5">
                 <button onClick={onClose} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-white z-10"><XCircle className="w-6 h-6" /></button>
                 <div className="p-8 border-b border-white/5 bg-gradient-to-br from-indigo-900/20 to-transparent"><h3 className="text-2xl font-bold text-white flex items-center gap-2"><Target className="w-6 h-6 text-indigo-400" />New Goal</h3><p className="text-slate-400 text-sm mt-1">Set a target and track your progress.</p></div>
                 <form onSubmit={handleSubmit} className="p-8 space-y-5">
                     <div><label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Goal Name</label><input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="e.g. Dream Vacation" /></div>
                     <div><label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Target Amount</label><div className="relative mt-2"><DollarSign className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" /><input required type="number" value={target} onChange={e => setTarget(e.target.value)} className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 pl-9 text-white focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-600" placeholder="10000" /></div></div>
                     <div>
                         <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Target Date</label>
                         <input 
                            required 
                            type="date" 
                            value={date} 
                            min={minDate}
                            onChange={e => setDate(e.target.value)} 
                            className="w-full bg-slate-950/50 border border-white/10 rounded-xl p-3.5 text-white mt-2 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all [color-scheme:dark]" 
                         />
                     </div>

                     {error && (
                         <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center gap-2 text-xs text-rose-300 font-bold animate-fade-in">
                             <AlertCircle className="w-4 h-4 shrink-0" />
                             {error}
                         </div>
                     )}

                     <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/20 mt-4 active:scale-95 transition-all">Start Saving</button>
                 </form>
             </div>
        </div>
    );
};

